// Parse and validate search parameters
const inputData = $input.all();

let query = '';
let collection_name = 'nomad_bms_documents';
let top_k = 5;
let score_threshold = 0.3;

if (inputData.length > 0) {
  const data = inputData[0].json;
  query = data.query || data.q || data.search || data.text || '';
  collection_name = data.collection || data.collection_name || 'nomad_bms_documents';
  top_k = parseInt(data.top_k || data.limit || data.k || 5);
  score_threshold = parseFloat(data.score_threshold || data.threshold || 0.3);
}

if (!query || query.trim() === '') {
  throw new Error('Missing required parameter: query');
}

return [{
  json: {
    query: query.trim(),
    collection_name: collection_name,
    top_k: top_k,
    score_threshold: score_threshold
  }
}];

// Format API response with metadata
const inputData = $input.all();

if (inputData.length === 0) {
  return [{
    json: {
      success: false,
      error: 'No response from search API',
      results: []
    }
  }];
}

const response = inputData[0].json;

if (response.detail || response.error) {
  return [{
    json: {
      success: false,
      error: response.detail || response.error,
      results: []
    }
  }];
}

if (!response.chunks || response.chunks.length === 0) {
  return [{
    json: {
      success: true,
      message: 'No results found',
      results: [],
      total_results: 0
    }
  }];
}

const formattedResults = response.chunks.map((chunk, index) => {
  const metadata = chunk.metadata || {};
  return {
    rank: index + 1,
    score: chunk.score ? chunk.score.toFixed(4) : 'N/A',
    content: chunk.content || chunk.text || '',
    document_name: metadata.document_name || 'Unknown',
    document_type: metadata.document_type || 'Unknown',
    page_number: metadata.page_number || null,
    chunk_type: metadata.chunk_type || 'unknown',
    standards: metadata.standards || [],
    categories: metadata.categories || []
  };
});

return [{
  json: {
    success: true,
    total_results: formattedResults.length,
    query: response.query || 'N/A',
    results: formattedResults,
    search_metadata: {
      collection: response.collection_name || 'bms_documents',
      execution_time_ms: response.execution_time_ms || null,
      timestamp: new Date().toISOString()
    }
  }
}];
